/* @autogenerated */
import type { HelperOptions } from 'handlebars';

/** Caracteres con significado en Markdown: en los datos se escapan para que se muestren tal cual. */
const MARKDOWN_SPECIAL = /[\\`*_[\]<>|~#]/g;

/** Cómo rellenar: idioma de los formatos y traducción de claves (`{{t 'clave'}}`). */
export interface RenderContext {
  lang: string;
  translate: (key: string, params?: Record<string, unknown>) => string;
}

/**
 * Rellena la plantilla Markdown `source` con `data` (Handlebars). Los textos de los datos se escapan para Markdown:
 * un `|` o un `*` en un nombre no rompe una tabla ni pone negritas. El Markdown de la plantilla se respeta.
 *
 * Helpers: `{{date valor}}`, `{{datetime valor}}`, `{{number valor decimales}}`, `{{t 'clave'}}`,
 * `{{default valor 'si no hay'}}`, `{{join lista ', '}}`, `{{#if (eq a b)}}`, `{{#each (sort lista 'campo')}}`.
 * Variables: `{{@now}}` (fecha de generación) y `{{@lang}}`, en cualquier nivel.
 */
export async function renderTemplate(source: string, data: unknown, context: RenderContext): Promise<string> {
  const { default: Handlebars } = await import('handlebars');
  const hb = Handlebars.create();
  registerHelpers(hb, context);
  // Variables disponibles en cualquier nivel: `{{@now}}`, `{{@lang}}`
  return hb.compile(source, { noEscape: true, strict: false })(escapeData(data), {
    data: { now: new Date(), lang: context.lang },
  });
}

/** Copia de `data` con los textos escapados para Markdown; fechas, números y booleanos quedan igual. */
export function escapeData(data: unknown, seen = new WeakMap<object, unknown>()): unknown {
  if (typeof data === 'string') {
    return escapeMarkdown(data);
  }
  if (!data || typeof data !== 'object' || data instanceof Date) {
    return data;
  }
  if (seen.has(data)) {
    return seen.get(data);
  }
  if (Array.isArray(data)) {
    const copy: unknown[] = [];
    seen.set(data, copy);
    data.forEach((item) => copy.push(escapeData(item, seen)));
    return copy;
  }
  const copy: Record<string, unknown> = {};
  seen.set(data, copy);
  Object.entries(data as Record<string, unknown>).forEach(([key, value]) => (copy[key] = escapeData(value, seen)));
  return copy;
}

export function escapeMarkdown(text: string): string {
  // Un salto de línea dentro de un valor rompería tablas y listas: se convierte en salto de línea de Markdown
  return text.replace(MARKDOWN_SPECIAL, (char) => '\\' + char).replace(/\r?\n/g, '  \n');
}

type Handlebars = typeof import('handlebars');

function registerHelpers(hb: Handlebars, context: RenderContext): void {
  const toDate = (value: unknown): Date | undefined => {
    if (value instanceof Date) {
      return isNaN(value.getTime()) ? undefined : value;
    }
    if (typeof value === 'string' || typeof value === 'number') {
      const date = new Date(value);
      return isNaN(date.getTime()) ? undefined : date;
    }
    return undefined;
  };
  // El último argumento de un helper siempre es `options`
  const args = (values: unknown[]) => values.slice(0, -1);

  hb.registerHelper('date', (value: unknown) => {
    const date = toDate(value);
    return date ? new Intl.DateTimeFormat(context.lang, { dateStyle: 'medium' }).format(date) : '';
  });
  hb.registerHelper('datetime', (value: unknown) => {
    const date = toDate(value);
    return date ? new Intl.DateTimeFormat(context.lang, { dateStyle: 'medium', timeStyle: 'short' }).format(date) : '';
  });
  hb.registerHelper('number', (...values: unknown[]) => {
    const [value, decimals] = args(values);
    const number = typeof value === 'number' ? value : Number(value);
    if (value === null || value === undefined || value === '' || isNaN(number)) {
      return '';
    }
    const digits =
      typeof decimals === 'number' ? { minimumFractionDigits: decimals, maximumFractionDigits: decimals } : {};
    return new Intl.NumberFormat(context.lang, digits).format(number);
  });
  hb.registerHelper('t', (...values: unknown[]) => {
    const [key, ...rest] = args(values);
    const options = values[values.length - 1] as HelperOptions;
    // Las claves llegan escapadas si salen de los datos (`{{t (concat 'scope.' status)}}`)
    const clean = String(key ?? '').replace(/\\(.)/g, '$1');
    return escapeMarkdown(context.translate(clean, { ...options.hash, ...(rest[0] as object) }));
  });
  hb.registerHelper('concat', (...values: unknown[]) =>
    args(values)
      .map((value) => value ?? '')
      .join(''),
  );
  hb.registerHelper('default', (...values: unknown[]) => {
    const [value, fallback] = args(values);
    return value === null || value === undefined || value === '' ? fallback : value;
  });
  hb.registerHelper('eq', (...values: unknown[]) => {
    const [a, b] = args(values);
    return a === b;
  });
  hb.registerHelper('join', (...values: unknown[]) => {
    const [list, separator] = args(values);
    return Array.isArray(list) ? list.join(typeof separator === 'string' ? separator : ', ') : '';
  });
  hb.registerHelper('sort', (...values: unknown[]) => {
    const [list, field] = args(values);
    if (!Array.isArray(list)) {
      return [];
    }
    const key = (item: any) => (typeof field === 'string' ? item?.[field] : item);
    return [...list].sort((a, b) => String(key(a) ?? '').localeCompare(String(key(b) ?? ''), context.lang));
  });
}
